INSERT INTO landing_sections (section_key, title, is_enabled, sort_order, content) VALUES
('locations','Browse by place',1,1,'{"title": "Find people in your town", "subtitle": "Pick a county or town to see who is nearby.", "show": "mixed", "count": 12}'),
('profiles','New faces',1,2,'{"title": "New faces near you", "subtitle": "Recently joined members, shown by distance once you sign in.", "cta_text": "See everyone", "cta_url": "/browse"}'),
('how_it_works','How it works',1,3,'{"title": "From hello to meeting in three steps", "subtitle": "No endless profiles to fill in, no pressure.", "items": [{"icon": "user-plus", "title": "Create your profile", "text": "Add a few photos, say what you are looking for and pick your interests. It takes about two minutes."}, {"icon": "compass", "title": "See who is nearby", "text": "Browse by swiping, a grid or a list. Everyone is shown by distance, so you meet people you can actually meet."}, {"icon": "message-circle", "title": "Say hello", "text": "When you both like each other, start a conversation. Take it at your own pace and meet when you are ready."}]}'),
('features','Why people choose us',1,4,'{"title": "Built around trust and privacy", "subtitle": "The things that make meeting new people feel safe.", "items": [{"icon": "badge-check", "title": "Verified profiles", "text": "Members can verify with a selfie, and verified profiles carry a badge."}, {"icon": "eye-off", "title": "You control what is visible", "text": "Hide your online status, distance and contact details, or browse in incognito."}, {"icon": "map-pin", "title": "Local by design", "text": "Results are ordered by how close people are, across all 47 counties."}, {"icon": "shield-check", "title": "Moderated and reportable", "text": "Photos are checked, and every profile has a block and report button."}, {"icon": "smartphone", "title": "Works like an app", "text": "Add it to your home screen from your browser. No app store needed."}, {"icon": "wallet", "title": "Pay with M-Pesa", "text": "Upgrade in seconds with M-Pesa. No card needed."}]}'),
('safety','Safety',1,5,'{"title": "Your safety comes first", "subtitle": "Simple habits that keep meeting people enjoyable.", "items": [{"icon": "video", "text": "Chat first, then move to a video call before you meet."}, {"icon": "map-pin", "text": "Meet in a public place and tell a friend where you are going."}, {"icon": "lock", "text": "Keep your phone number private until you trust the person."}, {"icon": "flag", "text": "Report anything that feels wrong. We review every report."}], "cta_text": "Read all safety tips", "cta_url": "/safety-tips"}'),
('hosts','Hosts',1,6,'{"title": "Need company for an evening or an event?", "subtitle": "Hosts are approved, ID-verified people offering friendly, professional company: dinners, city tours, travel and events. Book and pay a deposit securely.", "cta_text": "Meet the Hosts", "cta_url": "/hosts", "secondary_text": "Become a Host", "secondary_url": "/register?type=host", "bullets": ["ID-checked and approved by our team", "Clear rates and services up front", "Deposit held securely until the booking is confirmed"]}'),
('premium','Premium',1,7,'{"title": "Upgrade when you are ready", "subtitle": "Start free. Go Premium for unlimited likes and to see who likes you.", "cta_text": "Compare plans", "cta_url": "/pricing"}'),
('testimonials','Stories',1,8,'{"title": "What members say", "subtitle": "Real words from people on the site."}'),
('blog','From the blog',1,9,'{"title": "Advice for meeting people", "subtitle": "Short reads on dating, safety and making friends.", "count": 3}'),
('faq','Questions',1,10,'{"title": "Questions people ask", "subtitle": "Quick answers before you join.", "count": 5}'),
('cta','Join',1,11,'{"title": "Your next good conversation is nearby", "subtitle": "Create a free profile and see who is around you today.", "cta_text": "Create your profile", "cta_url": "/register", "secondary_text": "I already have an account", "secondary_url": "/login"}');
INSERT INTO faqs (category, question, answer, sort_order) VALUES
('Getting started','Is it free to join?','Yes. Creating a profile, browsing, liking and replying to messages are free. Premium plans add extras such as unlimited likes, seeing who likes you and advanced filters.',1),
('Getting started','Who can join?','Anyone aged 18 or over. We ask for your date of birth when you register and members who are under 18 are removed.',2),
('Getting started','How do I get more matches?','Add at least three clear photos, write a short bio, choose your interests and keep your location up to date. Complete profiles are shown to more people.',3),
('Getting started','Can I use it on my phone?','Yes. Open the site in your phone browser and choose "Add to home screen" for an app-like experience. There is nothing to download from an app store.',4),
('Privacy and safety','Who can see my photos?','You choose. Visitors who are not signed in may see blurred photos, depending on the site settings, and you can hide your online status, distance and last active time from your privacy settings.',5),
('Privacy and safety','Are my phone number and email visible?','Not unless you choose to share them. Contact details are hidden by default and only appear to the people the site allows, for example matched or Premium members, and only if you switch sharing on.',6),
('Privacy and safety','How do I report or block someone?','Open their profile or conversation and tap the three-dot menu. Blocking is instant and they will not be able to see or message you. Reports are reviewed by our team.',7),
('Privacy and safety','How does verification work?','Send a short selfie from your profile settings. Our team compares it with your photos and, if it matches, adds a verified badge to your profile.',8),
('Premium and payments','How do I pay?','You can pay with M-Pesa. You will receive a prompt on your phone to enter your PIN. Bank transfer is also accepted and is activated once our team confirms it.',9),
('Premium and payments','Can I cancel Premium?','Yes, any time from Billing. You keep your Premium features until the end of the period you paid for.',10),
('Premium and payments','What is a boost?','A boost puts your profile at the front of the line in your area for a short time so more people see you.',11),
('Hosts','What is a Host?','A Host is an approved, ID-verified member who offers friendly company for dinners, events, city tours and travel. Hosts set their own rates and services.',12),
('Hosts','How do bookings work?','Choose a Host, pick a date and time, and pay the deposit. The Host confirms the booking and you settle the balance with them directly. Cancellation rules are shown before you pay.',13),
('Hosts','Is this an escort service?','No. Hosts provide social company only. Sexual services are not permitted and any Host or client who asks for them is removed. Read the Host guidelines for details.',14);
INSERT INTO pages (title, slug, sort_order, show_in_footer, meta_title, meta_description, content, is_published) VALUES
('About us','about',1,0,'About ConnectHub','Meet the people behind ConnectHub and why we built it.','<p>ConnectHub helps people meet others who live nearby, for dating, friendship or good company. We built it because most apps show you people from everywhere and nowhere. Here, everyone is shown by how close they are, so a good conversation can turn into a coffee this week.</p><h2>What we care about</h2><ul><li><strong>Real people.</strong> Verified badges, moderated photos and a quick way to report anything that feels wrong.</li><li><strong>Privacy you control.</strong> You decide who sees your photos, your distance and your contact details.</li><li><strong>Built for Kenya.</strong> All 47 counties, M-Pesa payments and a design that works on any phone.</li></ul><h2>Get in touch</h2><p>Questions, feedback or a safety concern? <a href="/contact">Send us a message</a> and a real person will reply.</p>',1),
('Terms of service','terms-of-service',2,1,'Terms of service','The rules for using ConnectHub.','<p><em>Last updated: this page is yours to edit under Pages in the admin panel. Have it reviewed by a lawyer before launch.</em></p><h2>1. Using the service</h2><p>You must be at least 18 years old. You agree to provide accurate information, keep your password private and not share your account. We may suspend or remove accounts that break these terms.</p><h2>2. Your content</h2><p>You keep ownership of the photos and text you upload. You give us permission to display them on the service. You must own or have permission to use everything you upload. Do not upload nudity, violence, or images of other people without their consent.</p><h2>3. Behaviour</h2><p>Be respectful. Harassment, hate speech, scams, spam, impersonation and requests for money are not allowed. Do not use the service for anything illegal, including soliciting sexual services.</p><h2>4. Paid features</h2><p>Premium plans, boosts, gifts and Host bookings are paid in advance. Plans renew only when you choose to renew them. Refunds are given at our discretion unless the law requires otherwise.</p><h2>5. Hosts and bookings</h2><p>Hosts are independent members, not employees. They offer companionship services only. We take a commission on bookings made through the platform. Hosts and clients must follow the Host guidelines.</p><h2>6. Safety</h2><p>We do not run criminal background checks. Use your judgement when meeting people and follow our safety tips.</p><h2>7. Liability</h2><p>We provide the service as it is. To the extent the law allows, we are not responsible for what members do or say, or for losses from using the service.</p><h2>8. Changes and contact</h2><p>We may update these terms. If you keep using the service after a change you accept it. Questions? Use the <a href="/contact">contact page</a>.</p>',1),
('Privacy policy','privacy-policy',3,1,'Privacy policy','How ConnectHub collects, uses and protects your information.','<p><em>This page is yours to edit under Pages in the admin panel. Have it reviewed by a lawyer and align it with the Kenya Data Protection Act before launch.</em></p><h2>What we collect</h2><p>Information you give us (name, date of birth, gender, email, phone, photos, bio and preferences), your approximate location, messages you send, payment records (we never see your M-Pesa PIN), and technical data such as your device and IP address.</p><h2>How we use it</h2><p>To run the service, show you relevant people, keep the community safe, process payments, send notices you ask for, and improve the product.</p><h2>Who sees your information</h2><p>Other members see your profile according to your privacy settings and the site rules. Visitors who are not signed in may see limited, blurred profiles. We share data with payment providers and email services only as needed to run the service, and with authorities when the law requires it.</p><h2>Your choices</h2><p>You can edit or hide parts of your profile, pause your account, download your data or delete your account from Settings. Deleting your account removes your profile, photos and messages.</p><h2>Security</h2><p>Passwords are stored as one-way hashes. Connections use HTTPS. No system is perfectly secure, so please use a strong, unique password.</p><h2>Contact</h2><p>For privacy requests use the <a href="/contact">contact page</a>.</p>',1),
('Cookie policy','cookie-policy',4,1,'Cookie policy','What cookies ConnectHub uses.','<p>We use a small number of cookies. Essential cookies keep you signed in and protect forms from forgery. Optional analytics cookies are only set if you accept them.</p><ul><li><strong>Session cookie:</strong> keeps you signed in during your visit.</li><li><strong>Remember me:</strong> keeps you signed in for longer if you ask us to.</li><li><strong>Preferences:</strong> remembers your theme and cookie choice.</li></ul>',1),
('Safety tips','safety-tips',5,1,'Safety tips for meeting people','Practical advice for staying safe when you meet someone from the internet.','<p>Most people you meet here are exactly who they say they are. These habits keep it that way.</p><h2>Before you meet</h2><ul><li>Chat for a while first. Move to a video call to check they match their photos.</li><li>Look for the verified badge, but remember it is not a guarantee.</li><li>Never send money, even if the story is urgent or sad.</li><li>Keep your phone number, address and workplace private until you trust them.</li></ul><h2>When you meet</h2><ul><li>Choose a busy public place for the first meeting.</li><li>Tell a friend who you are meeting, where and when.</li><li>Arrange your own transport so you can leave when you want.</li><li>Keep an eye on your drink and trust your instincts.</li></ul><h2>If something feels wrong</h2><p>Leave, contact someone you trust, and <a href="/contact">report the profile</a>. In an emergency call 999 or 112.</p>',1),
('Community guidelines','community-guidelines',6,1,'Community guidelines','What we expect from every member.','<ul><li>Be kind and treat people with respect.</li><li>Use your own, recent photos. No fake or borrowed identities.</li><li>No nudity, sexual content or sexual solicitation.</li><li>No hate speech, threats or harassment.</li><li>No asking for money, gifts or financial help.</li><li>No spam, advertising or links to other platforms in your bio.</li><li>Respect a no. If someone is not interested, move on.</li></ul><p>Members who break these rules may be warned, suspended or removed. You can report anyone from their profile.</p>',1),
('Host guidelines','host-guidelines',7,1,'Host guidelines','Rules for Hosts and the people who book them.','<p>Hosts offer social company: dinners, events, city tours, travel and conversation. The service is non-sexual and the following rules apply to everyone.</p><h2>For Hosts</h2><ul><li>You must be 18 or over and pass ID verification before your profile goes live.</li><li>Describe your services and rates honestly. Do not offer or imply sexual services.</li><li>Do not take payment outside the platform for bookings made on it.</li><li>Keep to the agreed time and place. Cancel early if you cannot attend.</li><li>You can decline any booking and leave any situation you feel unsafe in.</li></ul><h2>For clients</h2><ul><li>Treat Hosts with respect. Companionship does not include physical or sexual contact.</li><li>Pay the deposit through the platform and the balance as agreed.</li><li>Do not pressure a Host to change the agreed plan or location.</li></ul><h2>Breaking the rules</h2><p>Accounts that offer or request sexual services are removed immediately and may be reported to the authorities.</p>',1);
INSERT INTO blog_posts (title, slug, category_id, excerpt, content, status, published_at, meta_title, meta_description) VALUES
('Five first-message openers that actually get replies','five-first-message-openers',(SELECT x.id FROM (SELECT id FROM blog_categories WHERE slug='dating-tips') x),'Skip "hey". These short openers start real conversations.','<p>A good first message is specific, short and easy to answer. Here are five that work.</p><h2>1. Pick something from their profile</h2><p>"You mentioned hiking in Ngong. Which trail is your favourite?" shows you read their profile and gives them something to talk about.</p><h2>2. Ask a light either-or</h2><p>Coffee or tea? Beach or mountains? Easy questions get quick answers.</p><h2>3. Share something small about yourself</h2><p>Mention a recent film, a place you tried or a song you cannot stop playing, then ask what they think.</p><h2>4. Be playful, not clever</h2><p>A little humour goes a long way, as long as it is kind.</p><h2>5. Keep it short</h2><p>Two or three lines is plenty. Save the long stories for later.</p>','published',NOW(),'Five first-message openers that actually get replies','Skip "hey". These short openers start real conversations.'),
('How to meet someone from the internet safely','meet-someone-safely',(SELECT x.id FROM (SELECT id FROM blog_categories WHERE slug='safety') x),'A simple checklist for the first meeting.','<p>Meeting someone new is exciting. A few habits make it safer too.</p><h2>Do a video call first</h2><p>Ten minutes on video confirms they look like their photos and feel like the person you have been chatting with.</p><h2>Meet in public</h2><p>Choose a busy cafe or restaurant. Avoid private places for the first meeting.</p><h2>Tell someone</h2><p>Share who you are meeting, where and when. Send a message when you are home.</p><h2>Trust your instincts</h2><p>If anything feels off, leave. You do not owe anyone an explanation.</p>','published',NOW(),'How to meet someone from the internet safely','A simple checklist for the first meeting.'),
('Making friends in a new town','making-friends-in-a-new-town',(SELECT x.id FROM (SELECT id FROM blog_categories WHERE slug='community') x),'Moving for work or study? Here is how to build a circle quickly.','<p>A new town can feel lonely for the first few months. These ideas help.</p><h2>Say yes to small invitations</h2><p>A coffee, a football game, a church service or a market visit. Small plans add up.</p><h2>Join something regular</h2><p>Running clubs, hiking groups, book clubs and volunteering all give you the same faces every week, which is how friendships form.</p><h2>Use your profile</h2><p>Choose "friendship" as what you are looking for on ConnectHub and browse people nearby who want the same.</p>','published',NOW(),'Making friends in a new town','Moving for work or study? Here is how to build a circle quickly.');
